#include <cstddef>
#include <optional>
#include <ranges>
#include <string>

/// Decodes a Base64-encoded string.
/// @param str The string to decode.
/// @returns The decoded bytes of *str*.
std::string decode(std::string_view str);

/// Decodes a Base64-encoded string that may be padded with '='.
/// @param str The string to decode.
/// @returns The decoded bytes of *str*, or `std::nullopt` if the input is not
///          valid Base64 padding.
template <class T = std::string>
std::optional<T> try_decode(std::string_view str) {
  auto result = T{};
  result.resize(decoded_size(str.size()));
  auto [written, read] = decode(result.data(), str.data(), str.size());
  if (read < str.size()) {
    // Only trailing '=' padding characters are allowed.
    for (size_t i = read; i < str.size(); ++i)
      if (str[i] != '=')
        return std::nullopt;
  }
  result.resize(written);
  return std::optional<T>{std::move(result)};
}

} // namespace tenzir::detail::base64

