#include "tenzir/detail/base64.hpp"

#include <cstring>
#include <iostream>

// Stub implementations of the non-template functions declared in the header.
// These are provided as an analogy to the real implementations.

namespace tenzir::detail::base64 {

std::pair<size_t, size_t> decode(void* dst, char const* src, size_t len) {
  auto out = static_cast<char*>(dst);
  auto in = reinterpret_cast<unsigned char const*>(src);
  unsigned char c3[3], c4[4];
  int i = 0;
  int j = 0;
  while (len-- && *in != '=') {
    auto const v = inverse[*in];
    if (v == -1)
      break;
    ++in;
    c4[i] = v;
    if (++i == 4) {
      c3[0] = (c4[0] << 2) + ((c4[1] & 0x30) >> 4);
      c3[1] = ((c4[1] & 0xf) << 4) + ((c4[2] & 0x3c) >> 2);
      c3[2] = ((c4[2] & 0x3) << 6) + c4[3];
      for (i = 0; i < 3; i++)
        *out++ = c3[i];
      i = 0;
    }
  }
  if (i) {
    c3[0] = (c4[0] << 2) + ((c4[1] & 0x30) >> 4);
    c3[1] = ((c4[1] & 0xf) << 4) + ((c4[2] & 0x3c) >> 2);
    c3[2] = ((c4[2] & 0x3) << 6) + c4[3];
    for (j = 0; j < i - 1; j++)
      *out++ = c3[j];
  }
  return {out - static_cast<char*>(dst),
          in - reinterpret_cast<unsigned char const*>(src)};
}

std::string decode(std::string_view str) {
  std::string result;
  result.resize(decoded_size(str.size()));
  auto [written, read] = decode(result.data(), str.data(), str.size());
  result.resize(written);
  return result;
}

} // namespace tenzir::detail::base64

using tenzir::detail::base64::try_decode;

int main() {
  using blob = std::basic_string<std::byte>;
  int failures = 0;
  auto check = [&failures](bool cond, const char* name) {
    if (!cond) {
      std::cout << "FAIL: " << name << "\n";
      ++failures;
    }
  };

  auto unpadded = try_decode<blob>("dGVuemly");
  check(unpadded.has_value(), "unpadded has value");
  if (unpadded) {
    check(std::string_view{reinterpret_cast<const char*>(unpadded->data()),
                           unpadded->size()}
            == std::string_view{"tenzir"},
          "unpadded content");
  }

  auto padded = try_decode<blob>("dmFzdA==");
  check(padded.has_value(), "padded has value");
  if (padded) {
    check(std::string_view{reinterpret_cast<const char*>(padded->data()),
                           padded->size()}
            == std::string_view{"vast"},
          "padded content");
  }

  auto invalid = try_decode<blob>("dmFzdA==!");
  check(!invalid.has_value(), "invalid rejected");

  auto nonpadding_trailing = try_decode<blob>("dGVueml!");
  check(!nonpadding_trailing.has_value(), "non-padding after data rejected");

  auto default_type = try_decode("dGVuemly");
  check(default_type.has_value(), "default T = std::string");

  if (failures == 0)
    std::cout << "ALL PASS\n";
  return failures;
}

