- name: Publish Functional Test Report
        uses: mikepenz/action-junit-report@v4
        if: always()
        with:
          report_paths: report.xml
          token: ${{ secrets.GITHUB_TOKEN }}
      - name: Save ccache Cache
        uses: actions/cache/save@v4
        with:
          path: ${{ env.CCACHE_DIR }}
          key: ${{ github.workflow }}-${{ matrix.tenzir.name }}-${{ matrix.tenzir.compiler }}-${{ needs.configure.outputs.head-ref-slug }}-${{ github.sha }}
      - name: Run Integration Tests

arguments.command:
python3 -c "
import yaml
d = yaml.safe_load(open('.github/workflows/tenzir.yaml'))
steps = d['jobs']['tenzir']['steps']
for s in steps:
    if 'cache' in s.get('name','').lower():
        print(s['name'], '|', s.get('uses'))
# find index of Save step relative to integration tests
names = [s.get('name') for s in steps]
for i,n in enumerate(names):
    if n and ('cache' in n.lower() or 'Integration' in n):
        print(i, '=>', n)
"

